$ErrorActionPreference = "Stop"

$ProjectRoot = "H:\MNTrapTeam\MNTrapTeam"
$Version = "4.6.0"

if (-not (Test-Path (Join-Path $ProjectRoot "mntrapteam"))) {
    throw "MNTrapTeam project not found at $ProjectRoot"
}

Write-Host "Installing MNTrapTeam $Version fast single-shoot + manual provisional tools..."

$scoutPayload = ""
$manualPayload = ""

[IO.File]::WriteAllBytes(
    (Join-Path $ProjectRoot "mntrapteam\recent_score_scout_cli.py"),
    [Convert]::FromBase64String($scoutPayload)
)
[IO.File]::WriteAllBytes(
    (Join-Path $ProjectRoot "mntrapteam\manual_score_cli.py"),
    [Convert]::FromBase64String($manualPayload)
)

Set-Content -Path (Join-Path $ProjectRoot "VERSION") -Value $Version -Encoding UTF8

$InitFile = Join-Path $ProjectRoot "mntrapteam\__init__.py"
if (Test-Path $InitFile) {
    $t = Get-Content $InitFile -Raw
    if ($t -match '__version__\s*=') {
        $t = [regex]::Replace(
            $t,
            '__version__\s*=\s*["''][^"'']+["'']',
            '__version__ = "4.6.0"',
            1
        )
    } else {
        $t = $t.TrimEnd() + "`r`n__version__ = `"4.6.0`"`r`n"
    }
    Set-Content -Path $InitFile -Value $t -Encoding UTF8
}

Set-Location $ProjectRoot

& ".\.venv\Scripts\python.exe" -m py_compile `
  ".\mntrapteam\recent_score_scout_cli.py" `
  ".\mntrapteam\manual_score_cli.py"
if ($LASTEXITCODE -ne 0) { throw "Syntax check failed." }

Write-Host ""
Write-Host "MNTrapTeam 4.6.0 installed."
Write-Host "Added fast --shoot-id mode and controlled manual provisional entry."
Write-Host ""
Write-Host "Fast John Berning preview:"
Write-Host '& ".\.venv\Scripts\python.exe" -m mntrapteam.recent_score_scout_cli preview --shoot-id 2117'
